const platform = $json.platform;
const raw = JSON.parse($json.raw_message);

// Label a group participant so the agent can tell who said what. WhatsApp does this
// backend-side in merge_payloads() while debouncing a burst; Telegram never touches the
// debouncer (it uses n8n's native trigger), so it is done here, once per message.
function tgSpeaker(m) {
  const f = (m && m.from) || {};
  return ((f.first_name || '') + ' ' + (f.last_name || '')).trim() || f.username || String(f.id || 'Unknown');
}

let text = '';
if (platform === 'whatsapp') {
  text = raw.messages[0].text.body;
} else if (platform === 'telegram') {
  text = raw.message.text;
  if ($json.group_id && text) {
    text = tgSpeaker(raw.message) + ': ' + text;
  }
} else if (platform === 'instagram') {
  text = raw.message ? raw.message.text : '';
}

return { text, platform, user_id: $json.user_id, chat_id: $json.chat_id, message_id: $json.message_id };

