  return ((f.first_name || '') + ' ' + (f.last_name || '')).trim() || f.username || String(f.id || 'Unknown');
}

let audioId = '';
let supplementaryText = raw.supplementary_text || '';
if (platform === 'whatsapp') {
  audioId = raw.messages[0].audio.id;
} else if (platform === 'telegram') {
  audioId = raw.message.voice.file_id;
  // Voice notes carry no caption, so without this a group voice note reaches the agent
  // with no indication of who sent it.
  if ($json.group_id) {
    const who = tgSpeaker(raw.message);
    supplementaryText = supplementaryText ? who + ': ' + supplementaryText : who + ' sent a voice note';
  }
} else if (platform === 'instagram') {
  audioId = raw.message && raw.message.attachments ? raw.message.attachments[0].payload.url : '';
}

return { platform, user_id: $json.user_id, chat_id: $json.chat_id, message_id: $json.message_id, audioId, supplementaryText };

