// Delivery fallback plus internal tool trace memory.
const items = $input.all();

function safeJson(value) {
  if (value == null || typeof value !== "string") return value;

  const trimmed = value.trim();
  if (!trimmed) return trimmed;

  try {
    return JSON.parse(trimmed);
  } catch {
    return trimmed;
  }
}

const secretKey =
  /(api[_-]?key|authorization|token|secret|password|cookie|credential|bearer|headers?)/i;

const importantKey =
  /(^id$|_id$|uuid$|status$|error$|message$|text$|content$|result$|results$|details$|show$|search_id$|quote_id$|booking_id$|payment_id$|installment_id$|customer_id$|entity_id$|user_id$|workflow_id$|offer_index$|offer_id$|booking_type$|payment_type$|origin$|destination$|departure_date$|return_date$|returnDate$|departureDate$|trip_type$|passenger_count$|cabin_class$|cabinClass$|oneWay$|numberOfBookableSeats$|totalTripduration$|currency$|base$|total$|price$|fare$|discount$|flexiTotal$|grandTotal$|convertedPrice$|conversionRate$|baggagePrice$|base_amount$|total_amount$|deposit_amount$|installment_amount$|balance_amount$|paid_amount$|outstanding$|carrier$|carrierCode$|carrierNumber$|operatingCarrierCode$|aircraftCode$|numberOfStops$|routeDuration$|iataCode$|terminal$|timestamp$|isReturn$|isVirtualInterlining$|isBlackListedInEU$|adult$|child$|children$|infant$|weight$|carryOn$|checkedBags$|allowance$|departure$|arrival$|routes$|outgoingRoutes$|returnRoutes$|cityRoutes$|itenaries$|itineraries$|segments$|quote$|display_name$|first_name$|middle_name$|last_name$|email$|phone$|version$|whatsapp_number$|preferred_currency$|lifecycle_stage$|profile_completed_at$|expires_at$|created_at$|updated_at$|due_date$|sequence_number$|release_level$|ticket_reference$|account_name$|bank_name$|activity_type$|description$|topic_key$|search_queries$|provider_reference$|provider$)/i;

function compact(value, depth = 0, parentKey = "") {
  value = safeJson(value);

  if (value == null) return undefined;

  if (typeof value === "string") {
    if (!importantKey.test(parentKey)) return undefined;
    return value.length > 1500 ? value.slice(0, 1500) + "..." : value;
  }

  if (typeof value === "number" || typeof value === "boolean") {
    return importantKey.test(parentKey) ? value : undefined;
  }

  if (depth > 8) return undefined;

  if (Array.isArray(value)) {
    const result = value
      .slice(0, 30)
      .map((entry) => compact(entry, depth + 1, parentKey))
      .filter((entry) => entry !== undefined);

    return result.length ? result : undefined;
  }

  if (typeof value === "object") {
    const output = {};

    for (const [key, raw] of Object.entries(value)) {
      if (secretKey.test(key)) continue;

      if (key === "account_number") {
        output[key] = "[REDACTED]";
        continue;
      }

      const child = compact(raw, depth + 1, key);
      if (child === undefined) continue;

      if (importantKey.test(key)) {
        output[key] = child;
        continue;
      }

      if (typeof child === "object" && child !== null) {
        const hasUsefulContent = Array.isArray(child)
          ? child.length > 0
          : Object.keys(child).length > 0;

        if (hasUsefulContent) output[key] = child;
      }
    }

    return Object.keys(output).length ? output : undefined;
  }

  return undefined;
}

function extractToolTrace(steps) {
  if (!Array.isArray(steps)) return [];

  const trace = [];

  for (const step of steps) {
    const action = step?.action || {};
    const tool = action.tool || action.toolName || action.name;

    if (!tool) continue;

    const input = compact(
      action.toolInput ?? action.input ?? action.args,
      0,
      "input",
    );

    const observation = compact(
      step.observation ?? step.output ?? step.result,
      0,
      "output",
    );

    const entry = { tool };

    if (input !== undefined) entry.input = input;
    if (observation !== undefined) entry.output = observation;

    trace.push(entry);
  }

  return trace.slice(0, 30);
}

function buildTrace(item) {
  const steps = item.json.intermediateSteps || [];
  const tools = extractToolTrace(steps);

  if (!tools.length) return "";

  const finalOutput = String(item.json.output ?? "").trim();

  const payload = {
    type: "internal_turn_trace",
    note:
      "Private continuity record. Use exact IDs, offer details, prices, statuses and customer-visible messages for future turns. Never expose this trace to the customer.",
    tools,
  };

  if (finalOutput) {
    payload.final_output =
      finalOutput.length > 2000
        ? finalOutput.slice(0, 2000) + "..."
        : finalOutput;
  }

  return "INTERNAL TURN TRACE: " + JSON.stringify(payload);
}

for (const item of items) {
  const output = String(item.json.output ?? "");
  const steps = item.json.intermediateSteps || [];

  const usedSendMessage =
    Array.isArray(steps) &&
    steps.some(
      (step) =>
        step?.action?.tool === "sendMessage" ||
        step?.action?.toolName === "sendMessage",
    );

  const workflowData = $("Workflow Data").first().json;
  const platformData = $("Merge Platforms").first().json;

  // Deliver the final output only when the agent did not call sendMessage.
  if (!usedSendMessage && output.trim()) {
    await this.helpers.httpRequest({
      method: "POST",
      url: workflowData.base_url + "/chat_messages/send-and-log",
      headers: {
        Authorization: "Bearer " + workflowData.webhook_secret,
      },
      body: {
        workflow_id: workflowData.workflow_id,
        platform_type: platformData.entity_platform,
        text: output,
        external_user_id: platformData.conversation_id,
        chat_id: platformData.chat_id,
      },
      json: true,
    });
  }

  const trace = buildTrace(item);

  if (!trace) {
    item.json.turnTraceMemoryStatus = {
      status: "skipped",
      reason: "No intermediate tool steps were found",
    };
    continue;
  }

  try {
    const response = await this.helpers.httpRequest({
      method: "POST",
      url: workflowData.base_url + "/chat_messages/log-agent-memory",
      headers: {
        Authorization: "Bearer " + workflowData.webhook_secret,
      },
      body: {
        workflow_id: workflowData.workflow_id,
        external_user_id: platformData.conversation_id,
        content: trace,
      },
      json: true,
    });

    if (response?.status !== "ok") {
      throw new Error("Memory endpoint returned: " + JSON.stringify(response));
    }

    item.json.turnTraceMemoryStatus = {
      status: "written",
      characters: trace.length,
      tool_count: Array.isArray(steps) ? steps.length : 0,
    };
  } catch (error) {
    item.json.turnTraceMemoryStatus = {
      status: "failed",
      characters: trace.length,
      error: String(error?.message || error),
    };
  }
}

return items;

